 void LinkExcel(){if(!Allowed())return;using(var d=new SaveFileDialog{Filter="Excel workbook (*.xlsx)|*.xlsx",FileName="Beam-Summary.xlsx",OverwritePrompt=false}){if(d.ShowDialog(this)!=DialogResult.OK)return;var next=new ExcelLiveLink(d.FileName);if(excelLink!=null)excelLink.Dispose();excelLink=next;beams.EndEdit();Recalculate();SyncExcel();}}
 void DisconnectExcel(){excelTimer.Stop();if(excelLink!=null)excelLink.Dispose();excelLink=null;excelStatus.Text="Excel: disconnected (workbook stays open)";}
 public object[,] ExcelRows(){var rows=new List<object[]>();double w=Options().Waste/100;foreach(var i in inputs.Where(x=>x.Result!=null))foreach(var g in i.Result.Lines.GroupBy(x=>new{x.Grade,x.Diameter})){double main=g.Where(x=>x.Part!="Stirrups"&&x.Part!="Side-face").Sum(x=>x.Kg),ties=g.Where(x=>x.Part=="Stirrups").Sum(x=>x.Kg),sfr=g.Where(x=>x.Part=="Side-face").Sum(x=>x.Kg),net=main+ties+sfr;rows.Add(new object[]{i.Description,i.Beam,i.ScheduleLabel,g.Key.Grade,g.Key.Diameter,main,ties,sfr,net*w,net*(1+w),Read(i.Length,"length"),int.Parse(i.Quantity)});}var result=new object[rows.Count,12];for(int r=0;r<rows.Count;r++)for(int c=0;c<12;c++)result[r,c]=rows[r][c];return result;}
 void SyncExcel(){if(excelLink==null)return;excelLink.Update(ExcelRows(),inputs.Any(i=>i.Result==null)?"PARTIAL - invalid entries excluded":"Live Beam Estimator summary");excelStatus.Text="Excel synced "+DateTime.Now.ToString("HH:mm:ss")+" | "+excelLink.PathName;} static DataGridView Grid(){var g=new DataGridView{AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,EnableHeadersVisualStyles=false,SelectionMode=DataGridViewSelectionMode.CellSelect,ColumnHeadersHeight=42,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(20,33,51);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",9,FontStyle.Bold);g.DefaultCellStyle.Padding=new Padding(4);g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(247,249,252);GridAppearance.Apply(g);return g;}
 static void Button(FlowLayoutPanel p,string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=30,FlatStyle=FlatStyle.Flat,BackColor=Color.White};b.Click+=(o,e)=>{try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"Beam estimator",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};p.Controls.Add(b);}
 static NumericUpDown Number(FlowLayoutPanel p,string label,decimal min,decimal max,decimal value,int decimals){var box=new FlowLayoutPanel{Width=120,Height=58,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(3,0,3,0)};box.Controls.Add(new Label{Text=label,UseMnemonic=false,Width=120,Height=20});var n=new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Increment=decimals==0?1:.25m,Width=114};box.Controls.Add(n);p.Controls.Add(box);return n;}
 static ComboBox Select(FlowLayoutPanel p,string label,string[] values){var box=new FlowLayoutPanel{Width=170,Height=58,FlowDirection=FlowDirection.TopDown,WrapContents=false};box.Controls.Add(new Label{Text=label,UseMnemonic=false,Width=170,Height=20});var c=new ComboBox{Width=165,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(values);c.SelectedIndex=0;box.Controls.Add(c);p.Controls.Add(box);return c;}
 bool Allowed(){if(AccessCodes.CanUseApp(2))return true;MessageBox.Show("Renew the eight-hour access to continue.");return false;}
 EstimateOptions Options(){return new EstimateOptions{LengthConfig=lengthProfile,GradeSmall=((SteelSelection)gradeSmall.SelectedItem).Grade,Grade=((SteelSelection)grade.SelectedItem).Grade,Fc=(double)concrete.SelectedItem,MainHook=mainHook.SelectedIndex==0?0:mainHook.SelectedIndex==1?90:180,Anchorage=anchorage.SelectedIndex,BondRatio=(double)bond.Value,Left=.25,Right=.25,Cover=(double)cover.Value,Hook=(double)hook.Value,Extra=(double)extra.Value,Waste=(double)waste.Value,Offset=50};} bool ReplaceOkay(){beams.EndEdit();Recalculate();return inputs.Count==0||State()==savedState||MessageBox.Show(this,"Replace the current estimate entries? Save them first if needed.","Load schedule",MessageBoxButtons.OKCancel)==DialogResult.OK;}
 void Choose(){if(!Allowed()||!ReplaceOkay())return;using(var d=new OpenFileDialog{Filter="Beam Formatter revised DXF (*.dxf)|*.dxf",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK){var files=d.FileNames.Select(path=>new[]{File.ReadAllText(path),Path.GetFileName(path)}).ToList();ValidateFiles(files,false);LoadCatalog(files[0][0],files[0][1]);foreach(var file in files.Skip(1))AppendCatalog(file[0],file[1]);}}
 void ChooseAdditional(){if(!Allowed())return;using(var d=new OpenFileDialog{Filter="Beam Formatter revised DXF (*.dxf)|*.dxf",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK){var files=d.FileNames.Select(path=>new[]{File.ReadAllText(path),Path.GetFileName(path)}).ToList();ValidateFiles(files,true);foreach(var file in files)AppendCatalog(file[0],file[1]);}}
 public void LoadCatalog(string raw,string name){RevisedSchedule.Read(raw,name);filling=true;try{beams.Rows.Clear();sources.Clear();schedules.Clear();inputs.Clear();((DataGridViewComboBoxColumn)beams.Columns[1]).Items.Clear();((DataGridViewComboBoxColumn)beams.Columns[13]).Items.Clear();}finally{filling=false;}AppendCatalog(raw,name);savedState=State();}
 public void AppendCatalog(string raw,string name){if(sources.Any(s=>s.Raw==raw))return;var a=RevisedSchedule.Read(raw,name);CheckUniqueMarks(sources.Concat(new[]{new ScheduleSource{Name=name,Raw=raw,Catalog=a,Rows=a.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)}}));string label=a.Floor+" | "+name;string initial=label;int suffix=2;while(sources.Any(s=>s.Label==label))label=initial+" ("+suffix+++ ")";var source=new ScheduleSource{Label=label,Name=name,Raw=raw,Catalog=a,Rows=a.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)};filling=true;try{sources.Add(source);catalog=sources[0].Catalog;sourceText=sources[0].Raw;sourceName=string.Join("; ",sources.Select(s=>s.Name));var mark=(DataGridViewComboBoxColumn)beams.Columns[1];if(!mark.Items.Contains(""))mark.Items.Add("");foreach(var row in a.Source){schedules[row.Mark]=row;if(!mark.Items.Contains(row.Mark))mark.Items.Add(row.Mark);}((DataGridViewComboBoxColumn)beams.Columns[13]).Items.Add(label);foreach(DataGridViewRow entry in beams.Rows)if(!entry.IsNewRow)ConfigureMarkCell(entry);}finally{filling=false;}sourceLabel.Text=sources.Count+" source DXF file(s) | "+sources.Sum(s=>s.Catalog.Source.Count)+" schedule marks | Floors: "+string.Join(", ",sources.Select(s=>s.Catalog.Floor).Distinct())+"\nEach entry: Description > Beam mark > Length(m) > Quantity. Source is automatic. Add DXF files retains existing entries.";Recalculate();}
 static void CheckUniqueMarks(IEnumerable<ScheduleSource> candidates){var conflicts=candidates.GroupBy(s=>s.Raw).Select(g=>g.First()).SelectMany(s=>s.Rows.Keys.Select(mark=>new{Mark=mark,Source=s.Name})).GroupBy(x=>x.Mark,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1).Take(10).ToList();if(conflicts.Count>0)throw new Exception("Duplicate beam marks across DXF files. Use unique marks before loading:\n"+string.Join("\n",conflicts.Select(g=>g.Key+": "+string.Join(" / ",g.Select(x=>x.Source)))));}
 void ValidateFiles(List<string[]> files,bool append){var candidates=append?sources.ToList():new List<ScheduleSource>();foreach(var file in files){var parsed=RevisedSchedule.Read(file[0],file[1]);candidates.Add(new ScheduleSource{Name=file[1],Raw=file[0],Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}CheckUniqueMarks(candidates);}
 BeamRow FindSchedule(string label,string mark){BeamRow row;return schedules.TryGetValue(mark,out row)?row:null;}
 void ConfigureMarkCell(DataGridViewRow row){var cell=(DataGridViewComboBoxCell)row.Cells[1];cell.Items.Clear();cell.Items.Add("");cell.Items.AddRange(schedules.Keys.OrderBy(k=>k,StringComparer.OrdinalIgnoreCase).Cast<object>().ToArray());} public int AddEntry(string description="",string mark="",string length="",string quantity="1",string schedule=""){if(!Allowed())return -1;if(sources.Count==0)throw new Exception("Load a revised schedule DXF first.");if(schedule=="")schedule=sources[0].Label;int index=beams.Rows.Add(description,mark.ToUpperInvariant(),"","",length,quantity,"","","","","","","",schedule);ConfigureMarkCell(beams.Rows[index]);beams.CurrentCell=beams.Rows[index].Cells[0];Recalculate();return index;}
 public string[] ScheduleLabels(){return sources.Select(s=>s.Label).ToArray();} void RemoveSelected(){if(!Allowed())return;foreach(var row in beams.SelectedCells.Cast<DataGridViewCell>().Select(c=>c.OwningRow).Distinct().Where(r=>!r.IsNewRow).OrderByDescending(r=>r.Index).ToList())beams.Rows.Remove(row);Recalculate();}
 static string Cell(DataGridViewRow r,int c){return Convert.ToString(r.Cells[c].Value).Trim();}
 static double Read(string s,string field){double value;if(!double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new Exception("Invalid "+field+". Use a decimal number.");return value;}
 public void Recalculate(){if(filling)return;filling=true;try{inputs.Clear();EstimateOptions o=Options();string settingsError="";try{o.Validate();}catch(Exception e){settingsError=e.Message;}
  foreach(DataGridViewRow row in beams.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int c=2;c<4;c++)row.Cells[c].Value="";for(int c=8;c<=12;c++)row.Cells[c].Value="";string description=Cell(row,0),mark=Cell(row,1).ToUpperInvariant(),length=Cell(row,4);if(description==""&&mark==""&&length=="")continue;
   var owner=sources.FirstOrDefault(s=>s.Rows.ContainsKey(mark));row.Cells[13].Value=owner==null?"":owner.Label;var input=new EstimateInput{Description=description,ScheduleLabel=Cell(row,13),Beam=mark,Length=length,Quantity=Cell(row,5),TieCount=Cell(row,6),TieCut=Cell(row,7)};inputs.Add(input);row.Tag=input;
   try{if(settingsError!="")throw new Exception(settingsError);if(description=="")throw new Exception("Enter a description");BeamRow schedule=FindSchedule(input.ScheduleLabel,mark);if(schedule==null)throw new Exception("Choose a beam mark from the revised DXF");input.Source=schedule;row.Cells[2].Value=schedule.Cell(0);row.Cells[3].Value=schedule.Cell(1);if(length=="")throw new Exception("Enter length in metres");int q;if(!int.TryParse(input.Quantity,out q)||q<=0||q>100000)throw new Exception("Quantity must be 1 to 100000 whole beams");int? count=null;if(input.TieCount!=""){int n;if(!int.TryParse(input.TieCount,out n))throw new Exception("Tie sets must be a whole number");count=n;}double? cut=input.TieCut==""?(double?)null:Read(input.TieCut,"tie cut m/set");input.Result=EstimatorEngine.Calculate(schedule,mark,Read(length,"beam length"),o,count,cut);foreach(var line in input.Result.Lines){if(q>1)line.Formula+=" PER BEAM x "+q+" beams";line.Metres*=q;line.Kg*=q;}input.Result.Ties=checked(input.Result.Ties*q);row.Cells[8].Value=input.Result.LongKg.ToString("N2");row.Cells[9].Value=input.Result.TieKg.ToString("N2");row.Cells[10].Value=input.Result.SfrKg.ToString("N2");row.Cells[11].Value=(input.Result.Total*(1+o.Waste/100)).ToString("N2");row.Cells[12].Value="Estimated | "+input.Result.Ties+" tie sets total";
   }catch(Exception e){input.Result=null;input.Error=e.Message;row.Cells[12].Value=e.Message;}
  }
  totals.Rows.Clear();var lines=inputs.Where(i=>i.Result!=null).SelectMany(i=>i.Result.Lines).ToList();foreach(var g in lines.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double kg=g.Sum(l=>l.Kg);totals.Rows.Add("\u00D8"+g.Key,kg.ToString("N2"),(kg*o.Waste/100).ToString("N2"),(kg*(1+o.Waste/100)).ToString("N2"));}gradeTotals.Rows.Clear();foreach(int steel in new[]{40,60}){var byGrade=lines.Where(l=>l.Grade==steel).ToList();foreach(var g in byGrade.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double kg=g.Sum(l=>l.Kg);gradeTotals.Rows.Add("G"+steel,"D"+g.Key,kg.ToString("N2"),(kg*o.Waste/100).ToString("N2"),(kg*(1+o.Waste/100)).ToString("N2"));}double subtotal=byGrade.Sum(l=>l.Kg);int r=gradeTotals.Rows.Add("G"+steel+" TOTAL","",subtotal.ToString("N2"),(subtotal*o.Waste/100).ToString("N2"),(subtotal*(1+o.Waste/100)).ToString("N2"));gradeTotals.Rows[r].DefaultCellStyle.BackColor=Color.FromArgb(220,233,247);}int done=inputs.Count(i=>i.Result!=null),quantity=inputs.Where(i=>i.Result!=null).Sum(i=>int.Parse(i.Quantity));status.Text=done+" / "+inputs.Count+" entries estimated | "+quantity+" beams | "+(done<inputs.Count?"PARTIAL TOTAL: ":"TOTAL: ")+(lines.Sum(l=>l.Kg)*(1+o.Waste/100)).ToString("N2")+" kg";
 }finally{filling=false;}ShowSelected();if(excelLink!=null){excelTimer.Stop();excelTimer.Start();}}
 void ShowSelected(){if(details==null||beams.CurrentRow==null||beams.CurrentRow.IsNewRow)return;var row=beams.CurrentRow;string desc=Cell(row,0),mark=Cell(row,1).ToUpperInvariant();var b=new StringBuilder();b.AppendLine(desc+" | "+mark+" | L="+Cell(row,4)+"m | Qty="+Cell(row,5));BeamRow schedule=FindSchedule(Cell(row,13),mark);if(schedule!=null){b.AppendLine("FLOOR / SOURCE: "+Cell(row,13));b.AppendLine("REVISED SCHEDULE: "+schedule.Cell(0)+" x "+schedule.Cell(1)+"mm");for(int c=0;c<3;c++)b.AppendLine(new[]{"LEFT   ","MIDSPAN","RIGHT  "}[c]+" bottom: "+string.Join(" + ",schedule.Cells[2+c])+" | top: "+string.Join(" + ",schedule.Cells[5+c]));b.AppendLine("Stirrups: "+schedule.Leg+" / "+schedule.Diameter+" / "+schedule.RevisedSpacing);b.AppendLine("SFR: "+schedule.Cell(11));}b.AppendLine("STATUS: "+Cell(row,12));var input=row.Tag as EstimateInput;if(input!=null&&input.Result!=null){foreach(var l in input.Result.Lines)b.AppendLine(EstimatorEngine.DisplayPart(l.Part)+" \u00D8"+l.Diameter+": "+l.Formula+" = "+l.Kg.ToString("0.00")+"kg");foreach(var n in input.Result.Notes)b.AppendLine("NOTE: "+n);}details.Text=b.ToString().Replace("%%C","\u00D8").Replace("%%c","\u00D8");}
 string State(){return string.Join("\n",sources.Select(s=>s.Label+s.Raw))+Options().Description()+(lengthProfile==null?"":ProfileState())+string.Join("\n",inputs.Select(i=>i.ScheduleLabel+"|"+i.Description+"|"+i.Beam+"|"+i.Length+"|"+i.Quantity+"|"+i.TieCount+"|"+i.TieCut));}
 public string Report(){beams.EndEdit();Recalculate();var o=Options();var b=new StringBuilder();int done=inputs.Count(i=>i.Result!=null);var lines=inputs.Where(i=>i.Result!=null).SelectMany(i=>i.Result.Lines).ToList();
  b.AppendLine("BEAM REINFORCEMENT - QUANTITY REVIEW");b.AppendLine("v"+Engine.Version+" | "+DateTime.Now.ToString("yyyy-MM-dd HH:mm"));b.AppendLine("Revised schedule: "+sourceName+" | Floor: "+string.Join(", ",sources.Select(s=>s.Catalog.Floor).Distinct()));b.AppendLine("Scope: "+done+" / "+inputs.Count+" entries | "+inputs.Where(i=>i.Result!=null).Sum(i=>int.Parse(i.Quantity))+" beams");
  if(done<inputs.Count)b.AppendLine("PARTIAL: incomplete/error entries below are excluded from totals.");b.AppendLine();b.AppendLine("MATERIALS / SETTINGS");b.AppendLine("Steel <=12mm: G"+o.GradeSmall+" (fy"+lengthProfile.FySmall+"MPa); >=16mm: G"+o.Grade+" (fy"+lengthProfile.FyLarge+"MPa) | fc="+o.Fc+"MPa");b.AppendLine("Calculation: "+lengthProfile.Name+" | "+(lengthProfile.Input.Simplified?"simplified":"general")+" | roundUP="+lengthProfile.Input.Round+"mm");b.AppendLine("Cover="+o.Cover+"mm | offset50mm | extra="+o.Extra.ToString("0.00")+"m/piece | waste="+o.Waste.ToString("0.00")+"%");b.AppendLine("Anchorage: "+(o.Anchorage==0?"none":o.Anchorage==1?"2Ld/piece":o.Anchorage==2?"lap/piece":"hookLdh at beam ends; Ld at cut ends")+" | end hooks="+(o.MainHook==0?"none":o.MainHook+"deg"));b.AppendLine("Unit weights: theoretical7850kg/m3 (NSCP2015 unit-mass table verification pending).");b.AppendLine();  b.AppendLine("WEIGHT SUMMARY BY DIAMETER");b.AppendLine(new string('-',100));b.AppendLine(string.Format("{0,-10}{1,10}{2,14}{3,14}{4,14}{5,14}","DIA mm","kg/m","LENGTH m","NET kg","WASTE kg","TOTAL kg"));
  foreach(var g in lines.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double kg=g.Sum(l=>l.Kg);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-10}{1,10:0.00}{2,14:0.00}{3,14:0.00}{4,14:0.00}{5,14:0.00}","D"+g.Key,EstimatorEngine.UnitMass(g.Key),g.Sum(l=>l.Metres),kg,kg*o.Waste/100,kg*(1+o.Waste/100)));}b.AppendLine("GRAND TOTAL: "+(lines.Sum(l=>l.Kg)*(1+o.Waste/100)).ToString("0.00",CultureInfo.InvariantCulture)+" kg (including waste)");b.AppendLine();
  b.AppendLine("STEEL GRADE TABULATION (selected <=12mm / >=16mm grade settings)");b.AppendLine(string.Format("{0,-9}{1,7}{2,13}{3,13}{4,13}{5,13}{6,13}","GRADE","DIA","MAIN kg","TIES kg","SFR kg","WASTE kg","TOTAL kg"));foreach(int steel in new[]{40,60}){var steelLines=lines.Where(l=>l.Grade==steel).ToList();foreach(var group in steelLines.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double net=group.Sum(l=>l.Kg);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-9}{1,7}{2,13:0.00}{3,13:0.00}{4,13:0.00}{5,13:0.00}{6,13:0.00}","G"+steel,group.Key,group.Where(l=>l.Part!="Stirrups"&&l.Part!="Side-face").Sum(l=>l.Kg),group.Where(l=>l.Part=="Stirrups").Sum(l=>l.Kg),group.Where(l=>l.Part=="Side-face").Sum(l=>l.Kg),net*o.Waste/100,net*(1+o.Waste/100)));}b.AppendLine("GRADE "+steel+" TOTAL = "+(steelLines.Sum(l=>l.Kg)*(1+o.Waste/100)).ToString("0.00")+" kg (including waste)");}b.AppendLine();
  b.AppendLine("BACKUP QUANTITIES BY DESCRIPTION");b.AppendLine(new string('-',100));for(int n=0;n<inputs.Count;n++){var i=inputs[n];b.AppendLine((n+1)+". "+i.Description+" | "+i.Beam+" | "+(i.Source==null?"B/D unavailable":"B="+i.Source.Cell(0)+"mm | D="+i.Source.Cell(1)+"mm")+" | L="+i.Length+"m each | Qty="+i.Quantity);if(i.Result==null)b.AppendLine("   NOT ESTIMATED: "+i.Error);else b.AppendLine("   Main="+i.Result.LongKg.ToString("0.00")+" | Stirrups="+i.Result.TieKg.ToString("0.00")+" | SFR="+i.Result.SfrKg.ToString("0.00")+" | Waste="+(i.Result.Total*o.Waste/100).ToString("0.00")+" | Total="+(i.Result.Total*(1+o.Waste/100)).ToString("0.00")+" kg");}
  int block=0;for(int n=0;n<inputs.Count;n++){var i=inputs[n];if(i.Result==null)continue;block++;if(block==1)b.AppendLine("\f");b.AppendLine("ENTRY "+(n+1)+" - "+i.Description);b.AppendLine("Floor / source: "+i.ScheduleLabel);b.AppendLine("Mark "+i.Beam+" | "+i.Source.Cell(0)+" x "+i.Source.Cell(1)+"mm | Length="+i.Length+"m EACH | Quantity="+i.Quantity);
   b.AppendLine("BOTTOM L/M/R: "+string.Join(" / ",Enumerable.Range(2,3).Select(c=>string.Join(" + ",i.Source.Cells[c]))));b.AppendLine("TOP    L/M/R: "+string.Join(" / ",Enumerable.Range(5,3).Select(c=>string.Join(" + ",i.Source.Cells[c]))));b.AppendLine("STIRRUPS: "+i.Source.Leg+" "+i.Source.Diameter+" | "+i.Source.RevisedSpacing+" | SFR: "+i.Source.Cell(11));int q=int.Parse(i.Quantity);
   b.AppendLine();b.AppendLine();b.AppendLine("CONTINUOUS / CUT MAIN BARS (same-diameter L/M/R reconciliation)");b.AppendLine(string.Format("{0,-30}{1,7}{2,10}{3,13}{4,14}","PIECE TYPE","DIA","PCS/BEAM","CUT m/pc","TOTAL m"));foreach(var line in i.Result.Lines.Where(l=>l.PiecesPerBeam>0))b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-30}{1,7}{2,10}{3,13:0.00}{4,14:0.00}",EstimatorEngine.DisplayPart(line.Part),line.Diameter,line.PiecesPerBeam,line.CutLength,line.Metres));b.AppendLine();AppendTieBreakdown(b,i,q);b.AppendLine();b.AppendLine();   b.AppendLine(string.Format("{0,-15}{1,9}{2,15}{3,9}{4,15}{5,12}{6,14}","COMPONENT","DIA mm","m / BEAM","QTY","TOTAL m","kg/m","WEIGHT kg"));
   foreach(var g in i.Result.Lines.GroupBy(l=>new{Part=l.Part=="Side-face"?"SFR":l.Part=="Stirrups"?"STIRRUPS":"MAIN BARS",l.Diameter}).OrderBy(g=>g.Key.Part).ThenBy(g=>g.Key.Diameter)){double metres=g.Sum(l=>l.Metres);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-15}{1,9}{2,15:0.00}{3,9}{4,15:0.00}{5,12:0.00}{6,14:0.00}",g.Key.Part,g.Key.Diameter,metres/q,q,metres,EstimatorEngine.UnitMass(g.Key.Diameter),g.Sum(l=>l.Kg)));}
   b.AppendLine("Waste="+(i.Result.Total*o.Waste/100).ToString("0.00")+"kg | TOTAL="+(i.Result.Total*(1+o.Waste/100)).ToString("0.00")+"kg");foreach(string note in i.Result.Notes.Where(t=>t.IndexOf("overlap",StringComparison.OrdinalIgnoreCase)>=0||t.IndexOf("Manual",StringComparison.OrdinalIgnoreCase)>=0))b.AppendLine("NOTE: "+note);b.AppendLine();b.AppendLine(new string('-',100));b.AppendLine();
  }b.AppendLine("## FINAL TOTAL - ALL ESTIMATED ENTRIES");b.AppendLine("Main bars: "+lines.Where(l=>l.Part!="Stirrups"&&l.Part!="Side-face").Sum(l=>l.Kg).ToString("0.00")+" kg");b.AppendLine("Stirrups:  "+lines.Where(l=>l.Part=="Stirrups").Sum(l=>l.Kg).ToString("0.00")+" kg");b.AppendLine("SFR:       "+lines.Where(l=>l.Part=="Side-face").Sum(l=>l.Kg).ToString("0.00")+" kg");b.AppendLine("Waste:     "+(lines.Sum(l=>l.Kg)*o.Waste/100).ToString("0.00")+" kg");b.AppendLine("GRAND TOTAL: "+(lines.Sum(l=>l.Kg)*(1+o.Waste/100)).ToString("0.00")+" kg (including waste)");if(done<inputs.Count)b.AppendLine("PARTIAL: incomplete/error entries excluded.");return b.ToString().Replace("%%C","\u00D8").Replace("%%c","\u00D8");
 }
 static void AppendTieBreakdown(StringBuilder b,EstimateInput input,int quantity){b.AppendLine("STIRRUP CUT LENGTHS & QUANTITIES");b.AppendLine(string.Format("{0,-30}{1,7}{2,10}{3,13}{4,14}","TYPE","DIA","PCS/BEAM","CUT m/pc","TOTAL m"));foreach(var line in input.Result.Lines.Where(l=>l.Part=="Stirrups")){int sets=line.TieSetsPerBeam>0?line.TieSetsPerBeam:input.Result.Ties/quantity;Action<string,double,int> row=(name,cut,pcs)=>{double metres=cut*pcs*quantity;b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-30}{1,7}{2,10}{3,13:0.00}{4,14:0.00}",name,line.Diameter,pcs,cut,metres));};if(line.TieOverride){row("Manual combined set",line.CutLength,sets);b.AppendLine("Manual cut override: component split is not available.");continue;}row("Main stirrup / hoop",line.MainHoopCut,sets);row("Additional leg (90+130)",line.AdditionalLegs==0?0:line.AdditionalLegCut,sets*line.AdditionalLegs);}} void ExportPdf(){if(!Allowed())return;beams.EndEdit();Recalculate();if(!inputs.Any(i=>i.Result!=null))throw new Exception("Add at least one valid estimate entry.");using(var d=new SaveFileDialog{Filter="Printable PDF (*.pdf)|*.pdf",FileName="Beam-Estimate-Backup.pdf"})if(d.ShowDialog(this)==DialogResult.OK){EstimatePdf.Write(d.FileName,Report());MessageBox.Show("Saved printable backup quantities and detailed calculations.\n"+d.FileName);}}
 public void SaveTo(string path){beams.EndEdit();Recalculate();if(catalog==null)throw new Exception("Load a revised DXF first.");var doc=new XmlDocument();var root=doc.CreateElement("BeamEstimate");root.SetAttribute("version","5");root.SetAttribute("sourceName",sourceName);doc.AppendChild(root);var sourceList=doc.CreateElement("ScheduleSources");root.AppendChild(sourceList);foreach(var item in sources){var source=doc.CreateElement("Source");source.SetAttribute("label",item.Label);source.SetAttribute("name",item.Name);source.InnerText=item.Raw;sourceList.AppendChild(source);}var settings=doc.CreateElement("Settings");var o=Options();double[] vals={o.GradeSmall,o.Grade,o.Fc,o.MainHook,o.Anchorage,o.BondRatio,o.Left,o.Right,o.Cover,o.Hook,o.Extra,o.Waste,o.Offset};string[] names={"gradeSmall","grade","fc","mainHook","anchorage","bond","left","right","cover","hook","extra","waste","offset"};for(int n=0;n<names.Length;n++)settings.SetAttribute(names[n],vals[n].ToString("R",CultureInfo.InvariantCulture));root.AppendChild(settings);if(lengthProfile!=null){var configuration=doc.CreateElement("LengthConfiguration");lengthProfile.Write(configuration);root.AppendChild(configuration);}foreach(var i in inputs){var e=doc.CreateElement("Entry");e.SetAttribute("schedule",i.ScheduleLabel);e.SetAttribute("description",i.Description);e.SetAttribute("mark",i.Beam);e.SetAttribute("length",i.Length);e.SetAttribute("quantity",i.Quantity);e.SetAttribute("tieCount",i.TieCount);e.SetAttribute("tieCut",i.TieCut);root.AppendChild(e);}string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);File.Copy(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}savedState=State();}
 public void OpenFrom(string path){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=100000000}))doc.Load(reader);var root=doc.DocumentElement;if(root==null||root.Name!="BeamEstimate"||!new[]{"3","4","5"}.Contains(root.GetAttribute("version")))throw new Exception("Use a revised-DXF estimate project from v1.4.1 or later.");var checkedSources=new List<ScheduleSource>();if(root["ScheduleSources"]!=null){foreach(XmlElement element in root.SelectNodes("ScheduleSources/Source")){var parsed=RevisedSchedule.Read(element.InnerText,element.GetAttribute("name"));checkedSources.Add(new ScheduleSource{Label=element.GetAttribute("label"),Name=element.GetAttribute("name"),Raw=element.InnerText,Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}}else{string raw=root["ScheduleDxf"].InnerText,name=root.GetAttribute("sourceName");var parsed=RevisedSchedule.Read(raw,name);checkedSources.Add(new ScheduleSource{Label=parsed.Floor+" | "+name,Name=name,Raw=raw,Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}if(checkedSources.Count==0||checkedSources.Select(s=>s.Label).Distinct().Count()!=checkedSources.Count)throw new Exception("Invalid or duplicate floor/source identifiers.");CheckUniqueMarks(checkedSources);foreach(XmlElement entry in root.SelectNodes("Entry")){string label=entry.HasAttribute("schedule")?entry.GetAttribute("schedule"):checkedSources[0].Label;var source=checkedSources.FirstOrDefault(s=>s.Label==label);if(source==null||(entry.GetAttribute("mark")!=""&&!source.Rows.ContainsKey(entry.GetAttribute("mark"))))throw new Exception("Project entry has a missing floor/source or beam mark.");}LoadCatalog(checkedSources[0].Raw,checkedSources[0].Name);sources[0].Label=checkedSources[0].Label;((DataGridViewComboBoxColumn)beams.Columns[13]).Items[0]=sources[0].Label;foreach(var source in checkedSources.Skip(1)){AppendCatalog(source.Raw,source.Name);sources[sources.Count-1].Label=source.Label;((DataGridViewComboBoxColumn)beams.Columns[13]).Items[sources.Count-1]=source.Label;}ApplyLengthConfiguration(root["LengthConfiguration"]==null?null:LengthConfiguration.Read(root["LengthConfiguration"]));filling=true;try{var e=root["Settings"];if(root["LengthConfiguration"]==null){gradeSmall.SelectedIndex=e.GetAttribute("gradeSmall")=="60"?1:0;grade.SelectedIndex=e.GetAttribute("grade")=="40"?1:0;SetConcrete(Read(e.GetAttribute("fc"),"fc"));lengthProfile=CalculationStore.Resolve((double)concrete.SelectedItem,((SteelSelection)gradeSmall.SelectedItem).Grade,((SteelSelection)gradeSmall.SelectedItem).Fy,((SteelSelection)grade.SelectedItem).Grade,((SteelSelection)grade.SelectedItem).Fy);}mainHook.SelectedIndex=e.GetAttribute("mainHook")=="180"?2:e.GetAttribute("mainHook")=="90"?1:0;anchorage.SelectedIndex=(int)Read(e.GetAttribute("anchorage"),"anchorage");NumericUpDown[] controls={bond,cover,hook,extra,waste};string[] names={"bond","cover","hook","extra","waste"};for(int n=0;n<names.Length;n++)controls[n].Value=(decimal)Read(e.GetAttribute(names[n]),names[n])*(names[n]=="left"||names[n]=="right"?100:1);CheckUniqueMarks(checkedSources);foreach(XmlElement entry in root.SelectNodes("Entry")){string label=entry.HasAttribute("schedule")?entry.GetAttribute("schedule"):sources[0].Label;int r=beams.Rows.Add(entry.GetAttribute("description"),entry.GetAttribute("mark"),"","",entry.GetAttribute("length"),entry.GetAttribute("quantity"),entry.GetAttribute("tieCount"),entry.GetAttribute("tieCut"),"","","","","",label);ConfigureMarkCell(beams.Rows[r]);}}finally{filling=false;}UpdateConfigurationLabel();Recalculate();savedState=State();} string ProfileState(){var d=new XmlDocument();var e=d.CreateElement("Configuration");lengthProfile.Write(e);return e.OuterXml;}
 void InitializeMaterials(){filling=true;try{gradeSmall.Items.Clear();grade.Items.Clear();concrete.Items.Clear();AddSteel(gradeSmall,40,275);AddSteel(gradeSmall,60,420);AddSteel(grade,60,420);AddSteel(grade,40,275);foreach(int fc in new[]{21,28,35})concrete.Items.Add((double)fc);foreach(var c in CalculationStore.All()){AddSteel(gradeSmall,c.GradeSmall,c.FySmall);AddSteel(grade,c.GradeLarge,c.FyLarge);if(!concrete.Items.Contains(c.Input.Fc))concrete.Items.Add(c.Input.Fc);}gradeSmall.SelectedIndex=0;grade.SelectedIndex=0;concrete.SelectedIndex=0;bond.Enabled=false;hook.Enabled=false;}finally{filling=false;}}
 static int AddSteel(ComboBox box,int grade,double fy){foreach(SteelSelection item in box.Items)if(item.Grade==grade&&item.Fy==fy)return box.Items.IndexOf(item);return box.Items.Add(new SteelSelection{Grade=grade,Fy=fy});}
 void SetConcrete(double fc){if(!concrete.Items.Contains(fc))concrete.Items.Add(fc);concrete.SelectedItem=fc;}
 void AutoConfiguration(){var s=(SteelSelection)gradeSmall.SelectedItem;var l=(SteelSelection)grade.SelectedItem;lengthProfile=CalculationStore.Resolve((double)concrete.SelectedItem,s.Grade,s.Fy,l.Grade,l.Fy);UpdateConfigurationLabel();Recalculate();}
 void StoredConfigurationChanged(){if(IsDisposed||profileSnapshot)return;double fc=(double)concrete.SelectedItem;var s=(SteelSelection)gradeSmall.SelectedItem;var l=(SteelSelection)grade.SelectedItem;filling=true;try{foreach(var c in CalculationStore.All()){AddSteel(gradeSmall,c.GradeSmall,c.FySmall);AddSteel(grade,c.GradeLarge,c.FyLarge);if(!concrete.Items.Contains(c.Input.Fc))concrete.Items.Add(c.Input.Fc);}gradeSmall.SelectedIndex=AddSteel(gradeSmall,s.Grade,s.Fy);grade.SelectedIndex=AddSteel(grade,l.Grade,l.Fy);SetConcrete(fc);}finally{filling=false;}AutoConfiguration();}
 void UpdateConfigurationLabel(){if(lengthProfile==null)return;calculationLabel.Text=(profileSnapshot?"Saved estimate calculation: ":"Automatic calculation: ")+lengthProfile.Name+" | "+(lengthProfile.Input.Simplified?"Simplified":"General bond ratio")+" | Round UP "+lengthProfile.Input.Round+"mm\nB and D come from the revised DXF. Concrete / steel selections choose the saved calculation values.";Text="Beam Estimator v"+Engine.Version+" | "+lengthProfile.Name;}
 public void ApplyLengthConfiguration(LengthConfiguration c){if(c==null){profileSnapshot=false;AutoConfiguration();return;}c.Validate();filling=true;try{lengthProfile=CalculationStore.Clone(c);profileSnapshot=true;gradeSmall.SelectedIndex=AddSteel(gradeSmall,c.GradeSmall,c.FySmall);grade.SelectedIndex=AddSteel(grade,c.GradeLarge,c.FyLarge);SetConcrete(c.Input.Fc);if(mainHook.SelectedIndex!=0&&anchorage.SelectedIndex==1)anchorage.SelectedIndex=3;}finally{filling=false;}UpdateConfigurationLabel();Recalculate();} void ShowCurtailment(){using(var f=new Form{Text="Curtailment Settings - Fixed",ClientSize=new Size(660,430),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10),BackColor=Color.FromArgb(242,245,249)}){var topGroup=new GroupBox{Text="Top steel curtailment location",Location=new Point(18,16),Size=new Size(300,105)};topGroup.Controls.Add(new Label{Text="End support                         L / 4\n\nContinuous support              L / 4",Dock=DockStyle.Fill,Padding=new Padding(12,12,0,0)});var bottom=new GroupBox{Text="Bottom steel curtailment location",Location=new Point(18,130),Size=new Size(300,145)};bottom.Controls.Add(new Label{Text="Midspan cutoff                     L / 6\n\nEnd support                         L / 4\n\nContinuous support              L / 4",Dock=DockStyle.Fill,Padding=new Padding(12,12,0,0)});var shear=new GroupBox{Text="Shear zone presets (reference)",Location=new Point(334,16),Size=new Size(307,259)};shear.Controls.Add(new Label{Text="Ductile beam\nDepth factor:  D x 2\n\nNon-ductile beam\nLength factor:  L / 3\n\nTie quantities follow the actual\nspacing/count pattern in revised DXF.",Dock=DockStyle.Fill,Padding=new Padding(12,12,0,0)});var note=new Label{Text="Fixed from supplied curtailment reference. Bottom midspan bars start L/6 from each end (body=2L/3). Continuous bars remain full length. Top middle-only cuts use the central L/2. Development/hook allowances are added separately.",Location=new Point(20,290),Size=new Size(620,76)};var ok=new Button{Text="OK",Location=new Point(535,378),Size=new Size(105,32),DialogResult=DialogResult.OK};f.Controls.AddRange(new Control[]{topGroup,bottom,shear,note,ok});f.AcceptButton=ok;f.CancelButton=ok;f.ShowDialog(this);}} bool SaveProjectDialog(){using(var d=new SaveFileDialog{Filter="Beam estimate project (*.beam-estimate.xml)|*.beam-estimate.xml",FileName="Beam-Estimate.beam-estimate.xml"}){if(d.ShowDialog(this)!=DialogResult.OK)return false;SaveTo(d.FileName);return true;}}
 void SaveProject(){if(Allowed())SaveProjectDialog();}void OpenProject(){if(!Allowed()||!ReplaceOkay())return;using(var d=new OpenFileDialog{Filter="Beam estimate project (*.beam-estimate.xml)|*.beam-estimate.xml"})if(d.ShowDialog(this)==DialogResult.OK)OpenFrom(d.FileName);}
}
